/* Staged victory previews around the trainer and partner; purely cosmetic. */
(()=>{
 let raf=0,canvas=null;const duration=3.5,clamp=n=>Math.max(0,Math.min(1,n)),fire=new Image();fire.src='assets/move-fx/emerald/fire.png';
 function stop(){cancelAnimationFrame(raf);raf=0;canvas?.remove();canvas=null}
 const colors=id=>({1:['#b4d986','#f1f0ab','#5c8b4d'],4:['#f4a060','#fff0b7','#cf6845'],7:['#89cbd6','#d8f6f3','#4c8fa8'],92:['#c79fdd','#f5d8fc','#8a619a'],95:['#b2a68c','#e3dac3','#766f62'],131:['#8bc8e1','#daf3fa','#5795b7'],144:['#b4e2eb','#efffff','#78a9cc'],150:['#c99ee1','#f4d4f4','#90699b']}[id]||['#f4d16e','#fff0bf','#c7933b']);
 function block(g,c,x,y,w,h){g.fillStyle=c;g.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
 function star(g,x,y,s,c){block(g,c,x-s,y-s,s*2,s*2);block(g,c,x-s*2,y-s/2,s*4,s);block(g,c,x-s/2,y-s*2,s,s*4)}
 function ring(g,x,y,r,c,alpha=1){g.save();g.globalAlpha*=alpha;for(let i=0;i<32;i++){const a=i*Math.PI/16;block(g,c,x+Math.cos(a)*r,y+Math.sin(a)*r*.26,3,2)}g.restore()}
 function fragment(g,x,y,s,angle){g.save();g.translate(Math.round(x),Math.round(y));g.rotate(angle);block(g,'#4c423a',-s,-s,s*2,s*2);block(g,'#a88b64',-s+2,-s+2,s*1.5,s*.8);block(g,'#d6bd8c',-s+2,-s+2,s*.7,2);g.restore()}
 function flame(g,x,y,t,s=30){if(!fire.complete||!fire.naturalWidth)return;const frame=Math.floor(t*14)%8;g.drawImage(fire,0,frame*32,32,32,Math.round(x-s/2),Math.round(y-s),s,s)}
 function play({effect,partner,arena}){stop();dispatchEvent(new Event('trainer-emote-stop'));const host=arena?document.getElementById('arenaView'):document.querySelector('.tp-scene');if(!host)return;canvas=document.createElement('canvas');canvas.width=arena?1280:240;canvas.height=arena?800:260;canvas.className='tp-victory-canvas';canvas.setAttribute('aria-hidden','true');canvas.style.cssText=arena?'position:absolute;inset:0;width:1280px;height:800px;z-index:2600;pointer-events:none':'position:absolute;inset:0;width:100%;height:100%;z-index:10;pointer-events:none';host.append(canvas);const g=canvas.getContext('2d'),palette=colors(partner),start=performance.now(),reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
  const bits=Array.from({length:38},(_,i)=>({x:14+(i*53)%212,y:-20-(i*19)%65,a:i*2.399,s:2+i%3,v:44+(i*13)%70,delay:i*.036}));
  function frame(now){if(!canvas||!host.isConnected){stop();return}const t=(now-start)/1000;if(t>=duration){stop();return}g.clearRect(0,0,canvas.width,canvas.height);g.save();if(arena)g.translate(273,370);g.imageSmoothingEnabled=false;const fade=clamp(t/.2)*clamp((duration-t)/.5);g.globalAlpha=fade;
   if(reduced){ring(g,104,222,65,palette[0],.6);for(let i=0;i<5;i++)star(g,38+i*38,88+(i%2)*10,2,palette[i%3])}
   else if(effect==='stars'){
    const age=t-.3;ring(g,104,222,50+Math.sin(t*2)*5,'#d5b560',.6);for(const p of bits){const a=age-p.delay;if(a<0||a>2.2)continue;g.globalAlpha=fade*clamp(a*5)*clamp((2.2-a)*2);const x=p.x+Math.sin(a*2+p.a)*8,y=p.y+a*p.v;star(g,x,y,p.s,['#fff0b4','#e9bc56','#cf9951'][Math.round(p.s)%3]);block(g,'#e6c477',x,y-14,1,7)}
   }else if(effect==='burst'){
    if(t<.55){const a=t/.55;ring(g,104,217,64*(1-a)+10,'#e3b879',1-a*.6);star(g,104,213,2+a*3,'#ffedb5')}
    const age=t-.55;if(age>0){for(const p of bits){const a=age-p.delay*.2;if(a<0||a>1.6)continue;const r=a*p.v*.8;g.globalAlpha=fade*clamp(1-a/1.6);const x=104+Math.cos(p.a)*r,y=207+Math.sin(p.a)*r*.65+a*a*24;star(g,x,y,Math.max(1,p.s-a*2),['#ffefb2','#efa16d','#c97347'][Math.round(p.s)%3])}if(age<1.35)for(let i=0;i<5;i++){g.globalAlpha=fade*clamp((1.35-age)*1.2);flame(g,54+i*26,225,t+i*.2,30+Math.sin(i+age)*7)}for(let i=0;i<9;i++){const a=age-i*.05;if(a<0||a>2)continue;g.globalAlpha=fade*(1-a/2)*.35;const x=104+Math.sin(i*2)*a*35,y=211-a*37,s=8+a*10;block(g,i%2?'#b4ac94':'#736c5c',x-s/2,y-s/2,s,s);block(g,'#b4ac94',x-s*.7,y-s*.2,s*1.4,s*.5)}}
   }else if(effect==='meteor'){
    if(t<1.35){const p=clamp((t-.2)/1.15),x=221-p*103,y=-35+p*257;if(t>.2){for(let i=10;i>0;i--){g.globalAlpha=fade*(1-i/11);star(g,x+i*4,y-i*8,3+i*.6,i%2?'#f0bf72':'#d38b5a')}g.globalAlpha=fade;fragment(g,x,y,11,t*2)}ring(g,118,223,23,'#d2b785',.4+Math.sin(t*5)*.1)}else{const a=t-1.35;ring(g,118,223,10+a*80,'#ceac71',clamp(1-a/1.5));for(let i=0;i<18;i++){const angle=i*2.399,r=a*(22+i*3);g.globalAlpha=fade*clamp(1-a/1.7);fragment(g,118+Math.cos(angle)*r,216+Math.sin(angle)*r*.35-a*34+a*a*34,2+i%3,a*4+i)}for(let i=0;i<8;i++){g.globalAlpha=fade*clamp(1-a/1.6)*.3;block(g,'#d8c69d',118+Math.cos(i)*a*53,216-a*18+Math.sin(i)*10,10+a*10,6+a*6)}}
   }else{
    const age=t-.25;ring(g,104,222,55+Math.sin(t*2)*4,palette[0],.6);for(let i=0;i<22;i++){const a=age-i*.045;if(a<0||a>2.7)continue;const angle=i*2.399+a*1.3,x=104+Math.cos(angle)*(50-a*5),y=212-a*39+Math.sin(angle)*13;g.globalAlpha=fade*clamp(a*3)*clamp(2.7-a);if([7,131,144].includes(partner)){g.strokeStyle=palette[i%3];g.lineWidth=2;g.strokeRect(Math.round(x),Math.round(y),4+i%3,4+i%3);block(g,palette[1],x+1,y+1,2,2)}else if(partner===4){flame(g,x,y,a+i*.1,17+i%3*3)}else if(partner===1){g.save();g.translate(x,y);g.rotate(angle);block(g,palette[i%3],-3,-1,7,3);block(g,palette[1],-1,-1,3,1);g.restore()}else if([92,150].includes(partner)){block(g,palette[i%3],x,y,4,7);block(g,palette[1],x+1,y,2,2)}else if(partner===95){fragment(g,x,y,3,a)}else{g.strokeStyle=palette[i%3];g.lineWidth=2;g.beginPath();g.moveTo(x-4,y-6);g.lineTo(x+1,y-1);g.lineTo(x-2,y+2);g.lineTo(x+4,y+6);g.stroke()}}}
   // Small pixel ribbon completes the sequence without hiding the duo.
   g.globalAlpha=fade*clamp((t-.4)*3);block(g,'#463723',44,37,152,29);block(g,'#aa8248',48,34,144,29);block(g,'#e7c884',52,37,136,2);g.font='bold 12px Arial';g.textAlign='center';g.fillStyle='#fff0c6';g.fillText('VITÓRIA!',120,54);g.restore();raf=requestAnimationFrame(frame)
  }raf=requestAnimationFrame(frame)
 }
 addEventListener('trainer-victory-preview',e=>play(e.detail));addEventListener('trainer-victory-stop',stop);addEventListener('pagehide',stop);
})();
